[CmdletBinding()]
param([switch]$PreflightOnly,[switch]$ExecuteOfficial,[ValidateRange(60,7200)][int]$TimeoutSeconds=1800)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if($PreflightOnly-and$ExecuteOfficial){throw 'Choose either -PreflightOnly or -ExecuteOfficial.'}
$study=$PSScriptRoot;$repo=(Resolve-Path (Join-Path $study '..\..')).Path;$profile=Get-Content -Raw (Join-Path $repo 'benchmark/harness/host-runner/host-runner-profile.json')|ConvertFrom-Json
function Json($v,$p){$t="$p.tmp";$v|ConvertTo-Json -Depth 30|Set-Content -LiteralPath $t -Encoding utf8;Move-Item -LiteralPath $t -Destination $p -Force}
function Sha($p){(Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash.ToLowerInvariant()}
function Blob($p){(git -C $repo rev-parse "HEAD:$p").Trim()}
function Port{$l=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,0);$l.Start();$p=([Net.IPEndPoint]$l.LocalEndpoint).Port;$l.Stop();$p}
$ids=[ordered]@{'benchmark/harness/candidate-runtime/Invoke-CandidateTurn.ps1'='a0565c4762405d651605ab60c4a2558f48d03e06';'benchmark/harness/candidate-runtime/candidate-runtime-profile.json'='a332696ad96444980d8ff436816f7c83d8033157';'benchmark/harness/host-runner/Invoke-BenchmarkHost.ps1'='e7594f2ac30ceb48d51717e9f55992862c4994bc'}
$runtimeRoot=$profile.runtimeRoot;New-Item -ItemType Directory -Force -Path $runtimeRoot|Out-Null;$run=Join-Path $runtimeRoot ('rawsql-v05-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $run|Out-Null
function Stop-Study($reason){Json @{result='FAIL';classification='MEASUREMENT-INVALID';reason=$reason;atUtc=[datetime]::UtcNow.ToString('o')} (Join-Path $run 'STOP.json');throw $reason}
function Assert-RuntimeLock {
 foreach($x in $ids.GetEnumerator()){if((Blob $x.Key)-ne$x.Value){Stop-Study "AUTHORITATIVE_BLOB_MISMATCH: $($x.Key)"}}
 $n=Resolve-CodexLaunchCommand;if($n.fileName-ne$lock.nativeCodex.path -or (Sha $n.fileName)-ne$lock.nativeCodex.sha256 -or ((& $n.fileName --version|Out-String).Trim())-ne$lock.nativeCodex.version){Stop-Study 'RUNTIME_LOCK_CHANGED'}
}
function Freeze-Source($source,$slotRoot){$target=Join-Path $slotRoot 'final-source';New-Item -ItemType Directory $target|Out-Null;Get-ChildItem -Force $source|Where-Object{$_.Name-ne'.git'}|Copy-Item -Destination $target -Recurse -Force;$manifest=@();Get-ChildItem -Recurse -File $target|ForEach-Object{$manifest+=@{path=$_.FullName.Substring($target.Length+1);sha256=(Sha $_.FullName)}};Json $manifest (Join-Path $slotRoot 'source-manifest.json');Compress-Archive -Path (Join-Path $target '*') -DestinationPath (Join-Path $slotRoot 'final-source.zip') -Force}
try {
 foreach($x in $ids.GetEnumerator()){if((Blob $x.Key)-ne$x.Value){Stop-Study "AUTHORITATIVE_BLOB_MISMATCH: $($x.Key)"}};. (Join-Path $repo 'benchmark/harness/candidate-runtime/Invoke-CandidateTurn.ps1');$native=Resolve-CodexLaunchCommand
 $lock=[ordered]@{baseCommit=(git -C $repo rev-parse HEAD).Trim();createdAtUtc=[datetime]::UtcNow.ToString('o');runtimeRoot=$runtimeRoot;nativeCodex=@{path=$native.fileName;sha256=(Sha $native.fileName);version=(& $native.fileName --version|Out-String).Trim()};powershell=$PSVersionTable.PSVersion.ToString();hostProcess=@{pid=$PID;name=(Get-Process -Id $PID).ProcessName};model=@{candidate='gpt-5.6-terra';candidateEffort='medium';reviewer='gpt-5.6-sol';reviewerEffort='high'};infrastructure=@();historicalValidationSha256=@{candidateLauncher='8e117cdb88761a219b30e09f3f21e632b44cddd513592e51c4dfb4a560b3a3f3';candidateProfile='46278fc07b16020d01623da1e4c90160eacbe8a266b2db1d4ee58dd7ff5fef22';hostRunner='cddb38ef4c572adf91faabf955869d4b2ba788c03b40476f20ee7f5d5fa73977'}};foreach($x in $ids.GetEnumerator()){$lock.infrastructure+=@{path=$x.Key;gitBlob=$x.Value;onDiskSha256=(Sha (Join-Path $repo $x.Key))}};Json $lock (Join-Path $run 'runtime-lock.json')
 if(-not$ExecuteOfficial){Json @{result='PASS';officialLaunchCount=0;runtimeLock=(Join-Path $run 'runtime-lock.json');mode='preflight-only'} (Join-Path $run 'preflight.json');Write-Output "PRECHECK_PASS $run";return}
 # These gates are non-study; they run only after the human deliberately supplies -ExecuteOfficial.
 Assert-RuntimeLock;& (Join-Path $repo 'benchmark/harness/host-runner/Invoke-BenchmarkHost.ps1') -Cycles 1;if($LASTEXITCODE -ne 0){Stop-Study 'CANDIDATE_RUNTIME_QUALIFICATION_FAILURE'}
 $probe=Join-Path $run 'reviewer-probe';New-Item -ItemType Directory $probe|Out-Null;Set-Content -LiteralPath (Join-Path $probe 'README.md') -Value 'reviewer qualification dummy';git -C $probe init -q;git -C $probe config user.email reviewer@example.invalid;git -C $probe config user.name reviewer;git -C $probe add .;git -C $probe commit -q -m baseline;Assert-RuntimeLock;$probeTurn=Invoke-CandidateTurn -WorkingDirectory $probe -Model 'gpt-5.6-sol' -ReasoningEffort 'high' -Sandbox 'read-only' -ApprovalPolicy 'never' -Prompt 'Read README.md and respond exactly OK. Do not modify files.' -JsonlPath (Join-Path $run 'reviewer-probe.jsonl') -StderrPath (Join-Path $run 'reviewer-probe.stderr.txt') -FinalResponsePath (Join-Path $run 'reviewer-probe.final.txt');$probeWait=Wait-CandidateTurn $probeTurn $TimeoutSeconds;$probeEvents=Get-Content -Raw (Join-Path $run 'reviewer-probe.jsonl');if($probeWait.timedOut -or $probeWait.exitCode -ne 0 -or $probeEvents -notmatch 'thread.started' -or $probeEvents -notmatch 'turn.started'){Stop-Study 'REVIEWER_QUALIFICATION_FAILURE'}
 & (Join-Path $study 'runner/Run-Calibrations.ps1');if($LASTEXITCODE -ne 0){Stop-Study 'CALIBRATION_FAILURE'};foreach($cycle in 1..3){& (Join-Path $study 'runner/Qualification.ps1') -Cycle $cycle -PostgresPort (Port) -ApplicationPort (Port);if($LASTEXITCODE -ne 0){Stop-Study "RUNNER_QUALIFICATION_FAILURE_$cycle"}}
 $state=[ordered]@{schemaVersion=1;gate='OPEN';officialLaunchCount=0;maximumOfficialLaunches=4;slots=@{}};Json $state (Join-Path $run 'official-launch-state.json');$order=(Get-Content -Raw (Join-Path $study 'execution-order.json')|ConvertFrom-Json).order;if(@($order).Count-ne4){Stop-Study 'INVALID_FROZEN_OFFICIAL_ORDER'}
 foreach($slot in $order){if($state.officialLaunchCount -ge 4){Stop-Study 'UNAUTHORIZED_FIFTH_CANDIDATE'};$task,$arm=$slot.Split('-');$slotRoot=Join-Path $run $slot;New-Item -ItemType Directory $slotRoot|Out-Null;$candidate=Join-Path $slotRoot 'candidate';& (Join-Path $study 'runner/Prepare-Arm.ps1') -Arm $arm -CandidatePath $candidate -IdentityOutputPath (Join-Path $slotRoot 'arm-identity.json');$identity=Get-Content -Raw (Join-Path $slotRoot 'arm-identity.json')|ConvertFrom-Json;if($LASTEXITCODE -ne 0 -or -not $identity.pass){Stop-Study "ARM_IDENTITY_FAILURE_$slot"};Assert-RuntimeLock;$turn=Invoke-CandidateTurn -WorkingDirectory $candidate -Model 'gpt-5.6-terra' -ReasoningEffort 'medium' -Sandbox 'danger-full-access' -ApprovalPolicy 'never' -Prompt (Get-Content -Raw (Join-Path $study "prompts/$task.txt")) -JsonlPath (Join-Path $slotRoot 'events.jsonl') -StderrPath (Join-Path $slotRoot 'stderr.txt') -FinalResponsePath (Join-Path $slotRoot 'final-response.txt');$wait=Wait-CandidateTurn $turn $TimeoutSeconds;$events=Get-Content -Raw (Join-Path $slotRoot 'events.jsonl');if($events -notmatch 'thread.started' -or $events -notmatch 'turn.started'){Stop-Study "PRELAUNCH_INFRA_FAILURE_$slot"};$state.officialLaunchCount++;$state.slots[$slot]=@{consumed=$true;process=$wait;startedAtUtc=[datetime]::UtcNow.ToString('o')};Json $state (Join-Path $run 'official-launch-state.json');Freeze-Source $candidate $slotRoot;& (Join-Path $study 'runner/Evaluate.ps1') -Task $task -CandidatePath $candidate -PostgresPort (Port) -ApplicationPort (Port) -OutputPath (Join-Path $slotRoot 'mechanical-primary.json');if($LASTEXITCODE -ne 0){Stop-Study "EVALUATOR_EXECUTION_FAILURE_$slot"}}
 # Blind reviews occur only after all candidate trees and primary results are frozen.
 $reviewMap=@();$reviewNo=0;foreach($slot in $order){$reviewNo++;$reviewId=('R{0:d2}' -f $reviewNo);$packet=Join-Path $run "blind-review-$reviewId";New-Item -ItemType Directory $packet|Out-Null;$source=Join-Path (Join-Path $run $slot) 'final-source';Get-ChildItem -Force $source|Where-Object{$_.Name -notin @('AGENTS.md','rules','SOURCE-MANIFEST.json')}|Copy-Item -Destination $packet -Recurse -Force;Copy-Item -LiteralPath (Join-Path $study "prompts/$($slot.Substring(0,3)).txt") -Destination (Join-Path $packet 'BUSINESS-REQUIREMENT.txt');Copy-Item -LiteralPath (Join-Path $study 'fixture/database/schema/001_inventory.sql') -Destination (Join-Path $packet 'CANONICAL-DDL.sql');$reviewPrompt='Review this opaque application packet for objective defects only. Return STRUCTURED JSON findings with findingId, objectiveCategory, concreteFailureCondition, expectedBehavior, predictedActualBehavior, minimalReproduction, confidence. Check PostgreSQL semantics, transactions, concurrency/idempotency, node-postgres runtime values, security, errors, and production build/start. Do not discuss SQL file style, parameter style, architecture, Rules conformance, formatting, comments, or maintainability. Do not modify files.';Assert-RuntimeLock;$reviewTurn=Invoke-CandidateTurn -WorkingDirectory $packet -Model 'gpt-5.6-sol' -ReasoningEffort 'high' -Sandbox 'read-only' -ApprovalPolicy 'never' -Prompt $reviewPrompt -JsonlPath (Join-Path $packet 'events.jsonl') -StderrPath (Join-Path $packet 'stderr.txt') -FinalResponsePath (Join-Path $packet 'findings.json');$reviewWait=Wait-CandidateTurn $reviewTurn $TimeoutSeconds;$reviewEvents=Get-Content -Raw (Join-Path $packet 'events.jsonl');if($reviewWait.timedOut -or $reviewWait.exitCode -ne 0 -or $reviewEvents -notmatch 'thread.started' -or $reviewEvents -notmatch 'turn.started'){Stop-Study "BLIND_REVIEW_FAILURE_$reviewId"};$reviewMap+=@{reviewId=$reviewId;slot=$slot;packet=$packet}}
 Json @{result='COMPLETE_PENDING_UNBLIND';officialLaunchCount=$state.officialLaunchCount;runtimeLock=(Join-Path $run 'runtime-lock.json');blindReviewMap=$reviewMap} (Join-Path $run 'RUN-SUMMARY.json')
}catch{if(-not(Test-Path (Join-Path $run 'STOP.json'))){Json @{result='FAIL';classification='MEASUREMENT-INVALID';reason=$_.Exception.Message} (Join-Path $run 'STOP.json')};throw}
